-- A table one of whose rows reached 18.6's TOAST threshold (2032 bytes) may hold a value
-- 18.6 compressed or moved out of line — this 3000-byte run of one character compresses,
-- and 18.6 reports the compressed size — and pglet models neither, so it refuses `0A000`
-- for every varlena of the table from then on. Documentary where 18.6 answers (any pglet
-- error passes).
-- @setup
CREATE TABLE pct (id int, b bytea);
INSERT INTO pct VALUES (1, '\');
-- @test
-- @expect-error: pg_column_size past the TOAST threshold
SELECT pg_column_size(b) FROM pct;
